css:
@page { size: A4 landscape; }
.estado-de-pago .table { width: 100%; }
.estado-de-pago .detalle { font-size: 9.5px; table-layout: auto; }
.print-format .estado-de-pago .detalle > thead > tr > th,
.print-format .estado-de-pago .detalle > tbody > tr > td { padding: 2px 4px; vertical-align: middle; }
.estado-de-pago .detalle thead { display: table-header-group; }
.estado-de-pago .detalle tr { page-break-inside: avoid; }
.estado-de-pago .firmas { width: 100%; margin-top: 56px; text-align: center; page-break-inside: avoid; }
.estado-de-pago .salto { page-break-before: always; }
.estado-de-pago .r { text-align: right; white-space: nowrap; }
.estado-de-pago .c { text-align: center; }
